-- Partners (ADR-0049). drizzle-kit emits the audit values, the table, ENABLE RLS,
-- the checks, the composite unique key, and the audit check. FORCE RLS and
-- the grants are hand-written. There is no DELETE grant: a Partner is archived.
ALTER TYPE "app"."audit_action" ADD VALUE 'partner.created';--> statement-breakpoint
ALTER TYPE "app"."audit_action" ADD VALUE 'partner.changed';--> statement-breakpoint
ALTER TYPE "app"."audit_action" ADD VALUE 'partner.archived';--> statement-breakpoint
ALTER TYPE "app"."audit_action" ADD VALUE 'partner.restored';--> statement-breakpoint
CREATE TABLE "app"."partners" (
	"tenant_id" uuid DEFAULT app.current_tenant_id() NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"phone" text,
	"email" text,
	"note" text,
	"archived_at" timestamp with time zone,
	CONSTRAINT "partners_name" CHECK ("app"."partners"."name" = btrim("app"."partners"."name") and length("app"."partners"."name") between 1 and 200),
	CONSTRAINT "partners_phone" CHECK ("app"."partners"."phone" is null or ("app"."partners"."phone" = btrim("app"."partners"."phone") and length("app"."partners"."phone") between 1 and 40)),
	CONSTRAINT "partners_email" CHECK ("app"."partners"."email" is null or ("app"."partners"."email" = btrim("app"."partners"."email") and length("app"."partners"."email") between 3 and 254 and position('@' in "app"."partners"."email") > 1 and position(' ' in "app"."partners"."email") = 0)),
	CONSTRAINT "partners_note" CHECK ("app"."partners"."note" is null or ("app"."partners"."note" = btrim("app"."partners"."note") and length("app"."partners"."note") between 1 and 2000))
);
--> statement-breakpoint
ALTER TABLE "app"."partners" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "app"."audit_entry" DROP CONSTRAINT "audit_entry_shape";--> statement-breakpoint
CREATE UNIQUE INDEX "partners_tenant_id_id" ON "app"."partners" USING btree ("tenant_id","id");--> statement-breakpoint
